// HNWI Prospection v2 - Email-first lead normalization
// Supports: LinkedIn, Facebook, Reddit, Google Alerts

const items = $input.all();
const processedLeads = [];

function parseBudget(raw) {
  const value = String(raw || '').trim();
  if (!value) return null;
  const millionMatch = value.match(/(\d+(?:[\.,]\d+)?)\s*M/i);
  if (millionMatch) return Math.round(parseFloat(millionMatch[1].replace(',', '.')) * 1000000);
  const eurMatch = value.replace(/\./g, '').match(/(\d{6,8})/);
  if (eurMatch) return Number(eurMatch[1]);
  return null;
}

function normalizeHnwiChannel(raw) {
  const value = String(raw || 'linkedin').trim().toLowerCase().replace(/[_\s]+/g, '-');
  if (['linkedin', 'facebook', 'reddit', 'google-alert'].includes(value)) return value;
  return 'other';
}

const resolvedOrgId = process.env.PUBLIC_CTA_ORG_ID || process.env.ORG_ID || '00000000-0000-0000-0000-000000000000';

for (const item of items) {
  const data = item.json;
  const hnwiChannel = normalizeHnwiChannel(data.channel || data.source || 'linkedin');
  const sourceChannel = ['linkedin', 'facebook', 'email', 'phone', 'website', 'instagram'].includes(hnwiChannel)
    ? hnwiChannel
    : 'other';

  const lead = {
    org_id: data.org_id || resolvedOrgId,
    external_id: 'hnwi-' + Date.now() + '-' + Math.random().toString(36).slice(2, 9),
    connector_name: `hnwi-prospection:${hnwiChannel}`,
    source_system: 'social',
    source_channel: sourceChannel,
    hnwi_source_channel: hnwiChannel,
    source_detail: 'n8n_hnwi_prospection_workflow_v2',
    name: data.name || data.fullName || 'HNWI Prospect',
    email: data.email || '',
    phone: data.phone || '',
    budget: parseBudget(data.budget || data.presupuesto),
    property_interest: data.interest || data.interes || 'Luxury villa / finca Mallorca',
    notes: data.notes || data.mensaje || 'High-intent HNWI signal detected',
    nationality: data.nationality || 'Unknown',
    zone_interest: data.zone || data.zona || 'Andratx / Calvia / Son Vida',
    email_verified: Boolean(data.email_verified || data.emailVerified || data.email),
    email_verification_source: data.email_verification_source || data.emailSource || 'manual_or_public',
    metadata: {
      raw_channel: data.channel || data.source || null,
      original_budget: data.budget || data.presupuesto || null,
      urgency: data.urgency || 'medium'
    }
  };

  processedLeads.push({ json: lead });
}

return processedLeads;

const lead = items[0].json;
console.log(`✅ Lead processed | lead_id: ${lead.lead_id || 'n/a'} | Tier: ${lead.qualification_tier || 'n/a'} | Score: ${lead.qualification_score || 'n/a'} | outreach_ready: ${lead.outreach_ready || false}`);
return items;
